import urllib.request, json; req = urllib.request.Request('http://127.0.0.1:8000/api/chat/execute-code/', method='POST'); req.add_header('Content-Type', 'application/json'); data = {'language': 'python', 'code': 'nums = list(map(int, input(\'Enter numbers: \').split())); print(nums)', 'user_input': '10 20 30'}; print(urllib.request.urlopen(req, data=json.dumps(data).encode()).read().decode())
